#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/aff3ct/codec_encoder.h>

void bind_codec_encoder(py::module& m)
{
    using codec_encoder = ::gr::aff3ct::codec_encoder;

    py::class_<codec_encoder, gr::fec::generic_encoder, std::shared_ptr<codec_encoder>>(
        m,
        "codec_encoder",
        py::multiple_inheritance(), // generic_encoder is a virtual base: pointers must be adjusted
        "Encoder of any AFF3CT code, described by its AFF3CT command line.")
        .def_static("make", &codec_encoder::make, py::arg("aff3ct_args"))
        .def("info_bits", &codec_encoder::info_bits)
        .def("coded_bits", &codec_encoder::coded_bits);
}
